function activeLocale(){var stored="";try{stored=(window.localStorage&&window.localStorage.getItem(LOCALE_KEY))||"";}catch(e){}
var hit=knownLocale(stored);if(hit)return hit;try{var navs=(window.navigator&&(window.navigator.languages||[window.navigator.language]))||[];for(var i=0;i<navs.length;i++){hit=knownLocale(navs[i]);if(hit)return hit;}}catch(e){}
try{hit=knownLocale(document.documentElement.getAttribute("lang"));if(hit)return hit;}catch(e){}
return LOCALE_DEFAULT;}
function setLocale(tag){var next=knownLocale(tag)||LOCALE_DEFAULT;try{if(window.localStorage)window.localStorage.setItem(LOCALE_KEY,next);}catch(e){}
applyLocale(next);rerenderChrome();if(settingsSt.built&&settingsEl&&!settingsEl.hidden){renderSettingsNav();navigateSettings(settingsSt.section);}
try{window.dispatchEvent(new CustomEvent("wps:locale",{detail:{lang:next}}));}catch(e){}}
function applyLocale(tag){try{document.documentElement.setAttribute("lang",tag);document.documentElement.setAttribute("dir",RTL[tag]?"rtl":"ltr");}catch(e){}
try{if(WP().setLocale)WP().setLocale(tag);}catch(e){}}
function applyStoredLocale(){applyLocale(activeLocale());}
function buildSettingsModal(){var field=searchField(t("Search"),filterSettingsNav,"wps-set-search");var searchInput=field.input;var navList=el("div","wps-set-nav-items");var nav=el("nav","wps-set-nav",{children:[field.el,navList]});var title=el("h2","wps-set-title");var close=el("button","wps-set-close",{attrs:{type:"button","aria-label":t("Close settings")},children:[icon("x",18)]});close.addEventListener("click",closeSettingsModal);var panel=el("div","wps-set-panel-body");var overlay=el("div","wps-set-overlay");overlay.addEventListener("click",closeSettingsModal);var modal=el("div","wps-set-modal",{children:[overlay,el("div","wps-set-dialog",{attrs:{role:"dialog","aria-modal":"true","aria-label":t("Settings")},children:[nav,el("div","wps-set-panel",{children:[el("div","wps-set-panel-head",{children:[title,close]}),panel]})]})]});modal.querySelector(".wps-set-dialog").addEventListener("click",function(e){e.stopPropagation();});modal.hidden=true;settingsRefs={nav:nav,title:title,panel:panel,list:navList,search:searchInput};settingsSt.built=true;renderSettingsNav();return modal;}
function renderSettingsNav(){if(!settingsRefs)return;var list=settingsRefs.list;list.textContent="";SETTINGS_SECTIONS.forEach(function(sec){var item=el("button","wps-set-nav-item",{attrs:{type:"button","data-section":sec.id},children:[el("span","wps-set-nav-icon",{children:[icon(sec.icon,18,"thin")]}),el("span","wps-set-nav-label",{text:t(sec.label)})],on:{click:function(){navigateSettings(sec.id);}}});if(sec.id===settingsSt.section)item.classList.add("is-active");list.appendChild(item);});list.appendChild(el("p","wps-set-empty wps-set-nav-empty",{text:t("No settings match your search.")}));filterSettingsNav(settingsSt.query);}
function sectionHaystack(sec){var parts=[sec.id,sec.label,sec.title];if(sec.keywords)parts=parts.concat(sec.keywords);if(sec.items){sec.items.forEach(function(it){parts.push(it.label);if(it.desc)parts.push(it.desc);});}
return parts.join(" ").toLowerCase();}
function filterSettingsNav(query){settingsSt.query=query||"";if(!settingsRefs)return;var q=settingsSt.query.toLowerCase().trim();var items=settingsRefs.list.querySelectorAll(".wps-set-nav-item");var shown=0;for(var i=0;i<items.length;i++){var sec=sectionById(items[i].getAttribute("data-section"));var hit=!q||(sec&&sectionHaystack(sec).indexOf(q)!==-1);items[i].hidden=!hit;if(hit)shown++;}
var empty=settingsRefs.list.querySelector(".wps-set-nav-empty");if(empty)empty.hidden=shown!==0;}
function navigateSettings(id){var sec=sectionById(id)||SETTINGS_SECTIONS[0];if(!sec)return;settingsSt.section=sec.id;if(settingsRefs){var items=settingsRefs.nav.querySelectorAll(".wps-set-nav-item");for(var i=0;i<items.length;i++){items[i].classList.toggle("is-active",items[i].getAttribute("data-section")===sec.id);}
settingsRefs.title.textContent=t(sec.title||sec.label);settingsRefs.panel.textContent="";settingsRefs.panel.scrollTop=0;try{sec.render(settingsRefs.panel);}
catch(e){settingsRefs.panel.appendChild(el("p","wps-set-empty",{text:t("This section couldn't be loaded.")}));}}
try{var want="#settings/"+sec.id;if(window.location&&window.history&&window.location.hash!==want){window.history.replaceState(null,"",window.location.pathname
+window.location.search+want);}}catch(e){}}
function openSettingsModal(section){if(typeof document==="undefined"||!document.body)return;if(!settingsEl){settingsEl=buildSettingsModal();document.body.appendChild(settingsEl);}
if(settingsSt.hideTimer){clearTimeout(settingsSt.hideTimer);settingsSt.hideTimer=null;}
var want=section||hashSettingsSection()||(SETTINGS_SECTIONS[0]&&SETTINGS_SECTIONS[0].id);navigateSettings(want);settingsEl.hidden=false;if(!settingsSt.releaseEsc){settingsSt.releaseEsc=claimEscape(function(){if(settingsSt.query){if(settingsRefs&&settingsRefs.search){settingsRefs.search.value="";}
filterSettingsNav("");return;}
closeSettingsModal();});}
var lift=function(){settingsEl.classList.add("is-active");};if(typeof requestAnimationFrame==="function"){requestAnimationFrame(lift);}else{lift();}}
function closeSettingsModal(){if(!settingsEl||settingsEl.hidden)return;closePanel();if(settingsSt.releaseEsc){settingsSt.releaseEsc();settingsSt.releaseEsc=null;}
settingsEl.classList.remove("is-active");if(settingsSt.hideTimer)clearTimeout(settingsSt.hideTimer);settingsSt.hideTimer=setTimeout(function(){settingsSt.hideTimer=null;if(settingsEl)settingsEl.hidden=true;},200);try{if(window.location&&window.history&&/#settings/.test(window.location.hash)){window.history.replaceState(null,"",window.location.pathname
+window.location.search);}}catch(e){}}
function hashSettingsSection(){try{var m=/#settings\/([a-z0-9_-]+)/i.exec(window.location.hash||"");if(m&&sectionById(m[1]))return m[1];}catch(e){}
return"";}
